"""Direct f25 comparisons in the retained ordinary Core VM; no cold/timing claim."""
from __future__ import annotations

from collections import Counter
import gzip
from hashlib import sha1, sha256
import json
import os
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parent
WORK = ROOT.parent
BASE = WORK / 'v83-native-receipt-union-r1/source'
CANDIDATE = WORK / 'v83-selfhost-emit-development-r1/source'
OUT = ROOT / 'actual-r1'
PHASES = (0, 1, 2, 3, 255)
WORKSPACE_LENGTHS = (0, 48, 49, 55, 56, 57, 58, 59, 60, 64)
CURSORS = (0, 1, 7, 255, 65535, (1 << 32) - 1)
ALIAS_CURSORS = (0, 1, 7, 48, 55, 56, 57, 58, 59, 60, 63, 255, 65535, (1 << 32) - 1)
VALUES = (0, 1, 255, 256, (1 << 63), (1 << 64) - 1)
OUTPUT_LENGTHS = (0, 1, 8, 64)
MAX_STEPS_PER_CASE = 10000
MAX_CALL_DEPTH = 32


def identity(data, mode=0o644):
    return {'bytes': len(data), 'sha256': sha256(data).hexdigest(),
            'blob': sha1(b'blob ' + str(len(data)).encode() + b'\0' + data).hexdigest(),
            'mode': '100755' if mode & 0o111 else '100644'}


def source_guard(root, expected):
    observed = {}
    for name, item in expected.items():
        path = root / name
        observed[name] = identity(path.read_bytes(), path.stat().st_mode)
        assert observed[name] == item, (str(root), name)
    return observed


def describe_error(error):
    return {'module': type(error).__module__, 'type': type(error).__name__,
            'code': getattr(error, 'code', None), 'message': str(error)}


def cases():
    for phase in PHASES:
        for size in WORKSPACE_LENGTHS:
            for cursor in CURSORS:
                for value in VALUES:
                    for output in OUTPUT_LENGTHS:
                        yield {'kind': 'separate', 'phase': phase, 'workspace_length': size,
                               'cursor': cursor, 'value': value, 'output_length': output}
    for phase in PHASES:
        for size in WORKSPACE_LENGTHS:
            for cursor in ALIAS_CURSORS:
                for value in VALUES:
                    yield {'kind': 'same-owner', 'phase': phase, 'workspace_length': size,
                           'cursor': cursor, 'value': value, 'output_length': size}
    for cursor in (255, 65535):
        for value in VALUES:
            yield {'kind': 'separate-success-high-cursor', 'phase': 2, 'workspace_length': 64,
                   'cursor': cursor, 'value': value, 'output_length': cursor + 1}


def main():
    OUT.mkdir(exist_ok=False)
    for name in tuple(os.environ):
        if name.startswith('HEPTA_HIA_'):
            del os.environ[name]
    sys.path.insert(0, str(BASE))
    from hepta.hia_agent_assembly import assemble_program
    from hepta.hia_program_runtime import _Machine, _Owner, _View

    original_manifest = (BASE.parent / 'FINAL-SOURCE-MANIFEST.json').read_bytes()
    candidate_manifest = (CANDIDATE.parent / 'CANDIDATE-SOURCE-MANIFEST.json').read_bytes()
    assert sha256(original_manifest).hexdigest() == '129db14408a555a7ff72f64fc45d4145eeda2e9884d42fb426541c259a0f0f3a'
    assert sha256(candidate_manifest).hexdigest() == 'c80af6993f6a7c83052c5ed31f300e54d68e29164fac7317cf8d6d5d0800c21a'
    expected = {'original': json.loads(original_manifest), 'candidate': json.loads(candidate_manifest)}
    roots = {'original': BASE, 'candidate': CANDIDATE}
    for label in roots:
        assert len(expected[label]) == 3324
        source_guard(roots[label], expected[label])
        (OUT / (label + '-SOURCE-MANIFEST.json')).write_bytes(original_manifest if label == 'original' else candidate_manifest)
    assert {name for name in expected['original'] if expected['original'][name] != expected['candidate'][name]} == {
        'tools/generate_hia_selfhost.py', 'examples/hia_bootstrap/selfhost.hiaasm'}

    class ObservedMachine(_Machine):
        def operation(self, instruction, environment, depth):
            if instruction['op'] not in ('buffer.load', 'buffer.store'):
                return super().operation(instruction, environment, depth)
            arguments = [environment[name] for name in instruction['args']]
            view = arguments[0]
            role = 'output' if view is self.output_view else 'workspace' if view is self.workspace_view else 'unexpected'
            assert role != 'unexpected'
            event = {'operation': instruction['op'], 'view': role, 'index': arguments[1]}
            if instruction['op'] == 'buffer.store':
                event['value'] = arguments[2]
            self.accesses.append(event)
            try:
                result = super().operation(instruction, environment, depth)
            except BaseException as error:
                event['error'] = describe_error(error)
                raise
            if instruction['op'] == 'buffer.load':
                event['value'] = environment[instruction['out'][0]['name']]
            event['completed'] = True
            return result

    programs, machines, documents, assembly_bytes = {}, {}, {}, {}
    for label, root in roots.items():
        raw = (root / 'examples/hia_bootstrap/selfhost.hiaasm').read_bytes()
        assembly_bytes[label] = raw
        programs[label] = assemble_program(raw)
        documents[label] = programs[label].as_dict()
        machines[label] = ObservedMachine(programs[label], MAX_STEPS_PER_CASE, 1 << 20, None, MAX_CALL_DEPTH)
        (OUT / (label + '-selfhost.hiaasm')).write_bytes(raw)
        (OUT / (label + '-generate_hia_selfhost.py')).write_bytes((root / 'tools/generate_hia_selfhost.py').read_bytes())
    old_functions = {function['name']: function for function in documents['original']['functions']}
    new_functions = {function['name']: function for function in documents['candidate']['functions']}
    assert len(old_functions) == len(new_functions) == 125 and old_functions.keys() == new_functions.keys()
    assert [name for name in old_functions if old_functions[name] != new_functions[name]] == ['f25']
    assert old_functions['f25']['params'] == new_functions['f25']['params']
    assert [item['type'] for item in old_functions['f25']['params']] == ['mutbuf', 'mutbuf', 'u64']
    counts = {label: {'functions': len(document['functions']),
                      'blocks': sum(len(function['blocks']) for function in document['functions']),
                      'ops': sum(len(block['ops']) for function in document['functions'] for block in function['blocks'])}
              for label, document in documents.items()}
    assert counts == {'original': {'functions': 125, 'blocks': 1459, 'ops': 8104},
                      'candidate': {'functions': 125, 'blocks': 1459, 'ops': 8152}}

    def invoke(machine, case):
        workspace = bytearray(((index * 29 + 17) & 255) for index in range(case['workspace_length']))
        if len(workspace) > 48:
            workspace[48] = case['phase']
        cursor_bytes = case['cursor'].to_bytes(4, 'little')
        for index, value in enumerate(cursor_bytes, 56):
            if index < len(workspace):
                workspace[index] = value
        if case['kind'] == 'same-owner':
            output = workspace
            output_root = workspace_root = _Owner(-1, workspace)
        else:
            output = bytearray(((index * 19 + 71) & 255) for index in range(case['output_length']))
            output_root, workspace_root = _Owner(-1, output), _Owner(-2, workspace)
        output_view, workspace_view = _View(output_root, True), _View(workspace_root, True)
        machine.output_view, machine.workspace_view = output_view, workspace_view
        machine.accesses = []
        machine.steps = 0
        resources_before = machine.resources()
        assert resources_before['allocations'] == resources_before['live_bytes'] == 0
        before = {'output_hex': bytes(output).hex(), 'workspace_hex': bytes(workspace).hex()}
        values, error = None, None
        try:
            values = machine.invoke(machine.functions['f25'], [output_view, workspace_view, case['value']])
        except BaseException as caught:
            error = describe_error(caught)
        resources_after = machine.resources()
        assert resources_after == resources_before
        assert all(x.active for x in (output_root, workspace_root, output_view, workspace_view))
        return {'before': before, 'output_hex': bytes(output).hex(), 'workspace_hex': bytes(workspace).hex(),
                'values': values, 'error': error, 'accesses': machine.accesses,
                'resources': resources_after, 'steps': machine.steps,
                'same_owner': output_root is workspace_root}

    def semantic(record):
        return {key: value for key, value in record.items() if key != 'steps'}

    differences = []
    summary = Counter()
    steps = {'original': [], 'candidate': []}
    streams = OUT / 'COMPLETE-OBSERVATIONS.jsonl.gz'
    total = 0
    with gzip.open(streams, 'wt', encoding='utf-8', compresslevel=6) as stream:
        for total, case in enumerate(cases(), 1):
            original = invoke(machines['original'], case)
            candidate = invoke(machines['candidate'], case)
            equal = semantic(original) == semantic(candidate)
            assert (original['error'] or {}).get('type') != 'HIAProgramBudgetExceeded'
            assert (candidate['error'] or {}).get('type') != 'HIAProgramBudgetExceeded'
            row = {'index': total, 'case': case, 'original': original, 'candidate': candidate,
                   'full_output_workspace_accesses_error_resources_equal': equal}
            stream.write(json.dumps(row, sort_keys=True, separators=(',', ':')) + '\n')
            summary[case['kind']] += 1
            summary['equal' if equal else 'different'] += 1
            summary['trap' if original['error'] is not None else 'returned'] += 1
            for label, value in (('original', original), ('candidate', candidate)):
                steps[label].append(value['steps'])
            if not equal:
                differences.append(total)
            if total % 2000 == 0:
                print(json.dumps({'completed': total, 'differences': len(differences)}), flush=True)

    marker = '  v54:usize = int.cast(v48) {"mode":"wrap"}\n'
    extra = ('  v1000:u64 = const() {"value":56}\n'
             '  v1001:u64 = const() {"value":1}\n'
             '  v1002:u64 = int.add.wrap(v48,v1001)\n'
             '  v1003:u64 = call(v45,v1000,v1002) {"function":"f38"}\n')
    candidate_text = assembly_bytes['candidate'].decode()
    assert candidate_text.count(marker) == 1
    mutant = candidate_text.replace(marker, extra + marker)
    mutant_program = assemble_program(mutant)
    (OUT / 'negative-store-before-output.hiaasm').write_text(mutant)
    mutant_machine = ObservedMachine(mutant_program, MAX_STEPS_PER_CASE, 1 << 20, None, MAX_CALL_DEPTH)
    negative_case = {'kind': 'separate', 'phase': 2, 'workspace_length': 64,
                     'cursor': 0, 'value': 0xdeadbeef, 'output_length': 0}
    candidate = invoke(machines['candidate'], negative_case)
    rejected = invoke(mutant_machine, negative_case)
    sensitivity = {'case': negative_case, 'candidate': candidate, 'mutant': rejected,
                   'detected': semantic(candidate) != semantic(rejected),
                   'same_original_output_trap': candidate['error'] == rejected['error'],
                   'cursor_side_effect_differs': candidate['workspace_hex'] != rejected['workspace_hex']}
    assert sensitivity['detected'] and sensitivity['same_original_output_trap'] and sensitivity['cursor_side_effect_differs']
    (OUT / 'NEGATIVE-CONTROL.json').write_text(json.dumps(sensitivity, sort_keys=True, indent=2) + '\n')

    for label in roots:
        source_guard(roots[label], expected[label])
    count = 0
    with gzip.open(streams, 'rt', encoding='utf-8') as stream:
        for count, line in enumerate(stream, 1):
            row = json.loads(line)
            assert row['index'] == count
            assert row['full_output_workspace_accesses_error_resources_equal'] == (semantic(row['original']) == semantic(row['candidate']))
    assert count == total == 11412
    record = {'schema': 'hia.selfhost-private-emit.vm-original-candidate.v83.r1',
              'status': 'PASS' if not differences else 'FAIL', 'scope': 'DEVELOPMENT_ONLY_ORDINARY_CORE_VM',
              'python': sys.version, 'base_commit': '4925e72d9f51f4dc3e8f4d1d2a7b24cce2f5772b',
              'candidate_tree': '75f48e03b16287cbcfc3235982e9aba201d6505e',
              'counts': counts, 'sole_changed_hia_function': 'f25', 'functions_unchanged': 124,
              'cases': total, 'summary': dict(summary), 'differences': differences,
              'steps': {label: {'minimum': min(values), 'maximum': max(values)} for label, values in steps.items()},
              'max_steps_per_case': MAX_STEPS_PER_CASE, 'max_call_depth': MAX_CALL_DEPTH,
              'vm_steps_recorded_but_not_equated': 'The transformation changes internal operation and call counts; no finite-budget equivalence is claimed.',
              'machine_reuse': 'The complete immutable function dictionary is retained; each case has fresh external owners/views and steps reset to zero; all resource counters remain zero.',
              'alias_scope': 'Two distinct mutable Views of one actual Owner stress physical alias order; this does not add an ownership admission claim.',
              'matrix': {'phases': PHASES, 'workspace_lengths': WORKSPACE_LENGTHS, 'cursors': CURSORS,
                         'alias_cursors': ALIAS_CURSORS, 'u64_values': VALUES, 'short_output_lengths': OUTPUT_LENGTHS},
              'complete_observations': {'path': streams.name, **identity(streams.read_bytes()),
                                        'gzip_crc_all_records_roundtrip_verified': True},
              'sensitive_negative_control': {key: sensitivity[key] for key in ('detected', 'same_original_output_trap', 'cursor_side_effect_differs')},
              'both_3324_source_manifests_unchanged': True, 'new_compilation': False,
              'new_timing_run': False, 'cold': False, 'native_qualification': False}
    (OUT / 'RESULT.json').write_text(json.dumps(record, sort_keys=True, indent=2) + '\n')
    print(json.dumps({key: record[key] for key in ('status', 'cases', 'summary', 'steps', 'sensitive_negative_control')}), flush=True)
    raise SystemExit(0 if not differences else 1)


if __name__ == '__main__':
    main()
